async function provePreparationObservations(control:import("../../../../🔒️leases/🟦️.ts").ResourceLeaseControl,original:import("../../../../📦️packages/🟦️typescript/🧭️routing/🟦️.ts").ScriptInvocation):Promise<void>{const routing=await import("../../../../📦️packages/🟦️typescript/🧭️routing/🟦️.ts"),{captureOwnedCommandResultV1}=await import("../../../../🎛️owned-execution/🟦️.ts"),sink=process.env.SEMIO_TEST_ARTIFACT_DIR;if(!sink)throw Error("Actual ticket DATA sink required");for(const row of corpus.preparationObservations){const directory=mkdtempSync(join(sink,"prepare-observe-"));try{const result=await captureOwnedCommandResultV1(process.execPath,["test",import.meta.path,"--test-name-pattern=^compiler cache isolated preparation observation$"],process.cwd(),{control,env:routing.scriptInvocationEnvironment(original,{...process.env,SEMIO_PREPARATION_OBSERVATION_CASE:row.name,SEMIO_PREPARATION_OBSERVATION_DIRECTORY:directory}),output:{maximumBytes:32768,maximumLines:256}});expect(result.status,result.stdout+result.stderr).toBe(0);const lines=result.stdout.split(/\r?\n/u).filter(line=>line.startsWith("[DEBUG] Preparation observation "));expect(lines).toHaveLength(1);console.log(lines[0]);}finally{rmSync(directory,{recursive:true,force:true});}}}

